                if not isinstance(raw, str) or not raw.strip():
                    continue
                text = _convert(raw, text_format)
                if not text or text in texts:
                    continue
                texts.append(text)
                evidence.append({"path": path, "span": None, "raw": raw, "value": text})
        if not texts:
            value = None
